        // Execute mint that exceeds max supply
        bool mintResult = token.mint(exceedAmount);

        // Verification: Should return true (incorrectly) without increasing supply
        assertTrue(mintResult, "Mint should return true even when failing");
        assertEq(
            token.totalSupply(),
            initialSupply,
            "Total supply should not increase when exceeding max supply"
        );
    }
}
